# aplicar-v58-solicitacao-admin-real-moderador.ps1
# Cria fluxo real:
# - Customer/Operator clica em Criar evento e preenche formulario.
# - Formulario envia para API Nest: /v1/admin-access-requests.
# - Moderador/Admin ve tudo em /admin/support/admin-requests.
# - Moderador aprova ou reprova.
# - Ao aprovar, o usuario vira ADMIN no banco.
# A dashboard NAO e alterada.

$ErrorActionPreference = "Stop"

$Root = Get-Location
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"

function Write-TextBase64File($RelativePath, $Base64Content) {
  $Target = Join-Path $Root $RelativePath
  $TargetDir = Split-Path $Target -Parent

  if (-not (Test-Path $TargetDir)) {
    New-Item -ItemType Directory -Path $TargetDir -Force | Out-Null
  }

  if (Test-Path $Target) {
    $Backup = "$Target.bak-v58-$Stamp"
    Copy-Item $Target $Backup -Force
    Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray
  }

  $Content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64Content))
  Set-Content -Path $Target -Value $Content -Encoding UTF8
  Write-Host "Atualizado: $RelativePath" -ForegroundColor Green
}

function Add-AdminAccessModelToPrisma() {
  $SchemaPath = Join-Path $Root "apps\api\prisma\schema.prisma"

  if (-not (Test-Path $SchemaPath)) {
    throw "schema.prisma nao encontrado em apps\api\prisma\schema.prisma"
  }

  $Schema = Get-Content $SchemaPath -Raw

  if ($Schema -match "model\s+AdminAccessRequest\s+\{") {
    Write-Host "Modelo AdminAccessRequest ja existe no Prisma." -ForegroundColor Yellow
    return
  }

  $Backup = "$SchemaPath.bak-v58-$Stamp"
  Copy-Item $SchemaPath $Backup -Force
  Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray

  $ModelBase64 = "__SCHEMA_MODEL_BASE64__"
  $ModelContent = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($ModelBase64))

  Add-Content -Path $SchemaPath -Value $ModelContent -Encoding UTF8
  Write-Host "Modelo AdminAccessRequest adicionado ao schema.prisma" -ForegroundColor Green
}

function Patch-AppModule() {
  $AppModulePath = Join-Path $Root "apps\api\src\app.module.ts"

  if (-not (Test-Path $AppModulePath)) {
    throw "app.module.ts nao encontrado em apps\api\src\app.module.ts"
  }

  $Content = Get-Content $AppModulePath -Raw

  if ($Content -notmatch "AdminAccessRequestsModule") {
    $Backup = "$AppModulePath.bak-v58-$Stamp"
    Copy-Item $AppModulePath $Backup -Force
    Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray

    $Content = $Content -replace "import \{ AiModule \} from './ai/ai.module';", "import { AiModule } from './ai/ai.module';`r`nimport { AdminAccessRequestsModule } from './admin-access-requests/admin-access-requests.module';"
    $Content = $Content -replace "(\s+AiModule,\s+)(\],)", "`$1AdminAccessRequestsModule,`r`n  `$2"

    Set-Content -Path $AppModulePath -Value $Content -Encoding UTF8
    Write-Host "AdminAccessRequestsModule adicionado ao app.module.ts" -ForegroundColor Green
  } else {
    Write-Host "AdminAccessRequestsModule ja esta no app.module.ts." -ForegroundColor Yellow
  }
}

Write-Host "Aplicando v58 - solicitacao real para suporte do moderador..." -ForegroundColor Cyan

$File0Base64 = ""
