Write-Host "Rodando Prisma automaticamente..." -ForegroundColor Cyan

$ApiPath = Join-Path $Root "apps\api"

if (-not (Test-Path $ApiPath)) {
  throw "Pasta apps\api nao encontrada. Confira se voce esta na raiz do projeto."
}

Push-Location $ApiPath

try {
  Write-Host "Executando: npx prisma db push" -ForegroundColor Cyan
  npx prisma db push

  if ($LASTEXITCODE -ne 0) {
    throw "npx prisma db push falhou. Veja o erro acima."
  }

  Write-Host "Executando: npx prisma generate" -ForegroundColor Cyan
  npx prisma generate

  if ($LASTEXITCODE -ne 0) {
    throw "npx prisma generate falhou. Veja o erro acima."
  }
}
finally {
  Pop-Location
}

